"""Generate Prometheus recording and alerting rules from SLO definitions."""

from __future__ import annotations

import re

import yaml

from .model import SLO
from .policies import POLICIES, RECORDING_WINDOWS

HEADER = (
    "# GENERATED by slogen from {source}. DO NOT EDIT BY HAND.\n"
    "# Change the SLO definition and run `make generate`; CI fails if this file is stale.\n"
)


def _selector(*parts: str) -> str:
    inner = ",".join(p for p in parts if p)
    return f"{{{inner}}}" if inner else ""


def error_ratio_expr(slo: SLO, window: str) -> str:
    """PromQL for the fraction of bad events over ``window``."""
    if slo.sli_type == "availability":
        bad = f"sum(rate({slo.metric}{_selector(slo.selector, slo.bad)}[{window}]))"
        total = f"sum(rate({slo.metric}{_selector(slo.selector)}[{window}]))"
        return f"{bad} / {total}"
    le_matcher = 'le="' + format(slo.threshold_seconds, "g") + '"'
    good = f"sum(rate({slo.metric}_bucket{_selector(slo.selector, le_matcher)}[{window}]))"
    total = f"sum(rate({slo.metric}_count{_selector(slo.selector)}[{window}]))"
    return f"1 - ({good} / {total})"


def _pascal(name: str) -> str:
    return "".join(part.capitalize() for part in re.split(r"[-_]", name))


def _num(value: float) -> str:
    return format(value, ".10g")


def recording_rules(slo: SLO) -> list[dict]:
    labels = {"service": slo.service, "slo": slo.name}
    rules = [
        {"record": f"slo:sli_error:ratio_rate{w}", "expr": error_ratio_expr(slo, w), "labels": dict(labels)} for w in RECORDING_WINDOWS
    ]
    rules.append(
        {
            "record": "slo:error_budget_remaining:ratio",
            "expr": f"1 - (({error_ratio_expr(slo, slo.window)}) / {_num(slo.error_budget)})",
            "labels": dict(labels),
        }
    )
    rules.append({"record": "slo:objective:ratio", "expr": _num(slo.objective / 100), "labels": dict(labels)})
    return rules


def alert_rules(slo: SLO) -> list[dict]:
    rules = []
    for p in POLICIES:
        threshold = _num(p.burn_rate * slo.error_budget)
        selector = f'{{service="{slo.service}",slo="{slo.name}"}}'
        long_rule = f"slo:sli_error:ratio_rate{p.long_window}{selector}"
        short_rule = f"slo:sli_error:ratio_rate{p.short_window}{selector}"
        annotations = {
            "summary": f"{slo.service}/{slo.name}: burning error budget {_num(p.burn_rate)}x too fast ({p.meaning})",
            "description": (
                f"Error ratio above {threshold} (burn rate {_num(p.burn_rate)}x of the {_num(slo.error_budget)} "
                f"budget for a {slo.objective:g}% objective) over both {p.long_window} and {p.short_window}."
            ),
        }
        if slo.runbook:
            annotations["runbook"] = slo.runbook
        rules.append(
            {
                "alert": f"{_pascal(slo.name)}{p.name}",
                "expr": f"{long_rule} > {threshold} and {short_rule} > {threshold}",
                "for": f"{p.for_minutes}m",
                "labels": {"severity": p.severity, "service": slo.service, "slo": slo.name},
                "annotations": annotations,
            }
        )
    return rules


def build_document(slos: list[SLO]) -> dict:
    groups = []
    for slo in slos:
        groups.append({"name": f"slo-{slo.service}-{slo.name}-recording", "interval": "30s", "rules": recording_rules(slo)})
        groups.append({"name": f"slo-{slo.service}-{slo.name}-alerts", "rules": alert_rules(slo)})
    return {"groups": groups}


def render(slos: list[SLO], source: str) -> str:
    body = yaml.safe_dump(build_document(slos), sort_keys=False, width=1000, default_flow_style=False)
    return HEADER.format(source=source) + body
